using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace SecureMessageQueue
{
    public class EncryptedStorageConfig
    {
        public byte[] MasterKey { get; set; }
        public string StoragePath { get; set; }
        public int MaxMessageSize { get; set; } = 65536;
    }

    public class QueueMessage
    {
        public string MessageId { get; set; }
        public string ContentType { get; set; }
        public byte[] Payload { get; set; }
        public Dictionary<string, string> Headers { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class MessageEnvelope
    {
        public byte[] IV { get; set; }
        public byte[] EncryptedPayload { get; set; }
        public byte[] HMAC { get; set; }
        public string EncodingScheme { get; set; }
    }

    public interface IEncodingResolver
    {
        Encoding ResolveEncoding(string scheme);
    }

    public class EncodingResolver : IEncodingResolver
    {
        private static readonly Dictionary<string, Encoding> _allowedEncodings = new Dictionary<string, Encoding>(StringComparer.OrdinalIgnoreCase)
        {
            { "utf-8", Encoding.UTF8 },
            { "utf-16", Encoding.Unicode },
            { "ascii", Encoding.ASCII },
            { "iso-8859-1", Encoding.GetEncoding(28591) }
        };

        public Encoding ResolveEncoding(string scheme)
        {
            if (string.IsNullOrEmpty(scheme))
                return Encoding.UTF8;

            string normalized = NormalizeEncodingName(scheme);
            if (_allowedEncodings.TryGetValue(normalized, out var encoding))
                return encoding;

            return Encoding.UTF8;
        }

        private string NormalizeEncodingName(string name)
        {
            return name.Replace(" ", "").Replace("_", "-").ToLowerInvariant();
        }
    }

    public class MessageDecryptor
    {
        private readonly byte[] _key;
        private readonly byte[] _hmacKey;

        public MessageDecryptor(byte[] masterKey)
        {
            using (var hkdf = new HMACSHA256(masterKey))
            {
                _key = hkdf.ComputeHash(Encoding.UTF8.GetBytes("encryption"));
                _hmacKey = hkdf.ComputeHash(Encoding.UTF8.GetBytes("authentication"));
            }
            Array.Resize(ref _key, 32);
        }

        public bool VerifyAndDecrypt(MessageEnvelope envelope, out byte[] plaintext)
        {
            plaintext = null;

            using (var hmac = new HMACSHA256(_hmacKey))
            {
                byte[] dataToAuth = CombineArrays(envelope.IV, envelope.EncryptedPayload);
                byte[] computedMac = hmac.ComputeHash(dataToAuth);

                if (!CryptographicEquals(computedMac, envelope.HMAC))
                    return false;
            }

            using (var aes = Aes.Create())
            {
                aes.Key = _key;
                aes.IV = envelope.IV;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var decryptor = aes.CreateDecryptor())
                {
                    plaintext = decryptor.TransformFinalBlock(
                        envelope.EncryptedPayload, 0, envelope.EncryptedPayload.Length);
                }
            }
            return true;
        }

        private static bool CryptographicEquals(byte[] a, byte[] b)
        {
            if (a.Length != b.Length) return false;
            int diff = 0;
            for (int i = 0; i < a.Length; i++)
                diff |= a[i] ^ b[i];
            return diff == 0;
        }

        private static byte[] CombineArrays(byte[] a, byte[] b)
        {
            byte[] result = new byte[a.Length + b.Length];
            Buffer.BlockCopy(a, 0, result, 0, a.Length);
            Buffer.BlockCopy(b, 0, result, a.Length, b.Length);
            return result;
        }
    }

    public class SecureMessageConsumer
    {
        private readonly EncryptedStorageConfig _config;
        private readonly MessageDecryptor _decryptor;
        private readonly IEncodingResolver _encodingResolver;

        public SecureMessageConsumer(EncryptedStorageConfig config, IEncodingResolver encodingResolver = null)
        {
            _config = config;
            _decryptor = new MessageDecryptor(config.MasterKey);
            _encodingResolver = encodingResolver ?? new EncodingResolver();
        }

        public async Task<QueueMessage> ConsumeMessageAsync(byte[] rawEnvelope)
        {
            if (rawEnvelope == null || rawEnvelope.Length == 0)
                throw new ArgumentException("Empty envelope");

            if (rawEnvelope.Length > _config.MaxMessageSize)
                throw new InvalidOperationException("Message exceeds maximum size");

            MessageEnvelope envelope = DeserializeEnvelope(rawEnvelope);
            ValidateEnvelope(envelope);

            if (!_decryptor.VerifyAndDecrypt(envelope, out byte[] plaintext))
                throw new CryptographicException("Message authentication failed");

            string textContent = DecodePayload(plaintext, envelope.EncodingScheme);
            QueueMessage message = ParseMessage(textContent);

            await PersistToStorageAsync(message);
            return message;
        }

        private MessageEnvelope DeserializeEnvelope(byte[] data)
        {
            string json = Encoding.UTF8.GetString(data);
            var envelope = JsonConvert.DeserializeObject<MessageEnvelope>(json);
            if (envelope == null)
                throw new FormatException("Invalid envelope format");
            return envelope;
        }

        private void ValidateEnvelope(MessageEnvelope envelope)
        {
            if (envelope.IV == null || envelope.IV.Length != 16)
                throw new FormatException("Invalid IV");
            if (envelope.EncryptedPayload == null || envelope.EncryptedPayload.Length == 0)
                throw new FormatException("Missing payload");
            if (envelope.HMAC == null || envelope.HMAC.Length != 32)
                throw new FormatException("Invalid HMAC");
        }

        private string DecodePayload(byte[] plaintext, string encodingScheme)
        {
            // Always decode as UTF-8 regardless of claimed encoding to prevent
            // encoding confusion attacks
            byte[] utf8Bytes = Encoding.UTF8.GetBytes(
                Encoding.UTF8.GetString(plaintext));
            return Encoding.UTF8.GetString(utf8Bytes);
        }

        private QueueMessage ParseMessage(string content)
        {
            try
            {
                return JsonConvert.DeserializeObject<QueueMessage>(content);
            }
            catch (JsonException ex)
            {
                throw new FormatException("Failed to parse message content", ex);
            }
        }

        private async Task PersistToStorageAsync(QueueMessage message)
        {
            if (message == null || string.IsNullOrEmpty(message.MessageId))
                throw new InvalidOperationException("Invalid message for storage");

            string sanitizedId = SanitizeFileName(message.MessageId);
            string filePath = Path.Combine(_config.StoragePath, sanitizedId + ".json");

            string fullPath = Path.GetFullPath(filePath);

            // Normalize the storage directory and enforce a trailing directory
            // separator so the prefix comparison cannot be bypassed by a sibling
            // directory whose name shares the storage path as a prefix
            // (e.g. '/data/store' vs '/data/store_other').
            string storageDir = Path.GetFullPath(_config.StoragePath);
            if (!storageDir.EndsWith(Path.DirectorySeparatorChar.ToString(), StringComparison.Ordinal))
                storageDir += Path.DirectorySeparatorChar;

            if (!fullPath.StartsWith(storageDir, StringComparison.OrdinalIgnoreCase))
                throw new UnauthorizedAccessException("Path traversal detected");

            byte[] storageData = EncryptForStorage(message);
            await File.WriteAllBytesAsync(fullPath, storageData);
        }

        private string SanitizeFileName(string input)
        {
            char[] invalid = Path.GetInvalidFileNameChars();
            StringBuilder sb = new StringBuilder(input.Length);
            foreach (char c in input)
            {
                if (Array.IndexOf(invalid, c) < 0 && c != '.' && c != '/')
                    sb.Append(c);
            }
            return sb.ToString();
        }

        private byte[] EncryptForStorage(QueueMessage message)
        {
            string json = JsonConvert.SerializeObject(message);
            byte[] plaintext = Encoding.UTF8.GetBytes(json);

            using (var aes = Aes.Create())
            {
                aes.Key = _config.MasterKey;
                aes.GenerateIV();
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var encryptor = aes.CreateEncryptor())
                {
                    byte[] ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
                    byte[] result = new byte[16 + ciphertext.Length];
                    Buffer.BlockCopy(aes.IV, 0, result, 0, 16);
                    Buffer.BlockCopy(ciphertext, 0, result, 16, ciphertext.Length);
                    return result;
                }
            }
        }
    }
}
